-- Baseline fertility engine rule set (v3.4), live for everyone. Generated from the console's status / mode design.

insert into public.engine_versions (version, status, rollout_pct, config, summary, live_at)
values ('v3.4', 'live', 100, $json${"pipeline": {"p95_ms": 180, "runs": "Runs on every new log and at 03:00 local time for all active users", "steps": [{"key": "inputs", "title": "Inputs", "icon": "tray", "items": ["BBT (manual / Oura)", "LH strip · AI read", "Cervical fluid", "Cycle history", "Symptoms"]}, {"key": "validate", "title": "Validate", "icon": "funnel", "items": ["Drop BBT if logged > 3h off usual time", "Flag fever (> 37.5°C)", "De-dup LH scans"]}, {"key": "score", "title": "Score", "icon": "sigma", "items": ["Weighted signal score 0–1", "Mode-specific weights", "Confidence from signal count"]}, {"key": "resolve", "title": "Resolve status", "icon": "flow", "items": ["Apply status rules (table)", "Confirm ovulation by 3-day BBT shift", "Recompute window"]}, {"key": "outputs", "title": "Outputs", "icon": "send", "items": ["Home status + ring", "Notification triggers", "Partner alerts", "Doctor report"]}]}, "statuses": [{"key": "pregnant", "name": "Pregnant", "color": "green", "icon": "baby", "order": 1, "category": "pregnancy", "modes": ["ttc", "pcos", "iui_ivf"], "description": "A positive test or hCG above 25 mIU/mL.", "entry": [[{"field": "positive_test", "op": "=", "value": "true"}], [{"field": "hcg", "op": ">", "value": "25"}]], "exit": [[{"field": "pregnancy_mode", "op": "=", "value": "false"}]], "copy": "“You're ~{weeks} weeks”", "default": false, "counts_as": [], "counts_mode": "pregnant"}, {"key": "menstrual", "name": "Menstrual", "color": "red", "icon": "drop", "order": 2, "category": "menstrual", "modes": ["ttc", "pcos", "iui_ivf", "after_loss"], "description": "Bleeding in the first days of the cycle.", "entry": [[{"field": "flow", "op": "≥", "value": "light"}, {"field": "cd", "op": "≤", "value": "7"}]], "exit": [[{"field": "flow_none_days", "op": "≥", "value": "1"}]], "copy": "“Period · day {cd}”", "default": false, "counts_as": ["Menstrual"]}, {"key": "peak", "name": "Peak", "color": "primary", "icon": "sparkle", "order": 3, "category": "fertile", "modes": ["ttc", "pcos", "after_loss"], "description": "LH surge or high LH with egg-white fluid.", "entry": [[{"field": "lh", "op": "=", "value": "peak"}], [{"field": "lh", "op": "=", "value": "high"}, {"field": "cm", "op": "=", "value": "egg_white"}]], "exit": [[{"field": "bbt_shift_confirmed", "op": "=", "value": "true"}], [{"field": "days_since_peak", "op": "≥", "value": "2"}]], "copy": "“Peak fertility today”", "default": false, "counts_as": ["Peak fertility"]}, {"key": "high_fertility", "name": "High fertility", "color": "pink", "icon": "sun", "order": 4, "category": "fertile", "modes": ["ttc", "pcos", "after_loss"], "description": "Fertile window before the peak.", "entry": [[{"field": "score", "op": "≥", "value": "0.55"}, {"field": "days_to_ov", "op": "≤", "value": "5"}]], "exit": [[{"field": "status", "op": "=", "value": "peak"}], [{"field": "score", "op": "<", "value": "0.4"}]], "copy": "“High chance today”", "default": false, "counts_as": ["High fertility"]}, {"key": "two_week_wait", "name": "Two-week wait", "color": "blue", "icon": "hourglass", "order": 5, "category": "luteal", "modes": ["ttc", "pcos", "iui_ivf", "after_loss"], "description": "Days after confirmed ovulation until the test.", "entry": [[{"field": "ovulation_confirmed", "op": "=", "value": "true"}, {"field": "dpo", "op": "≥", "value": "1"}]], "exit": [[{"field": "period_started", "op": "=", "value": "true"}], [{"field": "test_result", "op": "≠", "value": "none"}]], "copy": "“{dpo} DPO · test in {n} days”", "default": false, "counts_as": ["Luteal · 2WW", "Post-ovulation"]}, {"key": "low_fertility", "name": "Low fertility", "color": "gray", "icon": "moon", "order": 6, "category": "follicular", "modes": ["ttc", "pcos", "after_loss"], "description": "Default when no other status matches.", "entry": [], "exit": [], "copy": "“Low chance today”", "default": true, "counts_as": ["Low fertility"]}], "modes": {"ttc": {"meta": {"label": "TTC", "title": "Trying to conceive (default)", "color": "primary", "icon": "target", "description": "Baseline rule set for regular cycles (21–45 days). All other modes inherit these values and override only what differs."}, "weights": {"lh": 0.4, "cf": 0.25, "bbt": 0.2, "calendar": 0.1, "skin": 0.05, "protocol": 0}, "params": [{"key": "cycle_len", "label": "Valid cycle length", "value": "21–45 days", "hint": "outside range → irregular flag"}, {"key": "luteal", "label": "Assumed luteal phase", "value": "13 days", "hint": "personalised after 3 cycles"}, {"key": "fertile_window", "label": "Fertile window length", "value": "6 days", "hint": "5 before + ovulation day"}, {"key": "lh_rule", "label": "LH rule for Peak", "value": "1 peak OR high + egg-white"}, {"key": "bbt_confirm", "label": "BBT shift to confirm", "value": "+0.2 °C × 3 days"}, {"key": "min_signals", "label": "Min. signals for confidence", "value": "2 in last 5 days"}, {"key": "late_alert", "label": "Late-period alert", "value": "cycle + 3 days"}], "status_overrides": [{"status": "peak", "kind": "same", "copy": "“Peak fertility today”"}, {"status": "high_fertility", "kind": "same", "copy": "“High chance today”"}, {"status": "two_week_wait", "kind": "same", "copy": "“{dpo} DPO · test in {n} days”"}, {"status": "low_fertility", "kind": "same", "copy": "“Low chance today”"}], "notifications": [{"key": "window_opens", "title": "Fertile window opens", "detail": "Push at 07:00 on first high day", "enabled": true}, {"key": "peak_day", "title": "Peak day", "detail": "Push + partner alert", "enabled": true}, {"key": "test_day", "title": "Test day reminder", "detail": "12 DPO · 07:00", "enabled": true}, {"key": "late_period", "title": "Late period alert", "detail": "Cycle + 3 days", "enabled": true}], "features": [{"key": "test_countdown", "title": "Pregnancy test countdown", "detail": "Shown during 2WW", "enabled": true}, {"key": "partner_alerts", "title": "Partner alerts", "detail": "Fertile window & peak", "enabled": true}, {"key": "specialist_nudge", "title": "Specialist nudge", "detail": "After 12 months (6 if 35+)", "enabled": true}, {"key": "community", "title": "Community: TTC 6+ months group", "detail": "Suggested after cycle 6", "enabled": true}]}, "pcos": {"meta": {"label": "PCOS", "title": "Irregular cycles / PCOS", "color": "amber", "icon": "pulse", "description": "No fixed ovulation date. Predictions wait for real signs; isolated LH highs are treated as possible false surges. Longer cycles never trigger late alerts."}, "weights": {"lh": 0.45, "cf": 0.3, "bbt": 0.2, "calendar": 0.0, "skin": 0.05, "protocol": 0}, "params": [{"key": "cycle_len", "label": "Valid cycle length", "value": "21–90 days", "base": "21–45"}, {"key": "luteal", "label": "Assumed luteal phase", "value": "13 days"}, {"key": "fertile_window", "label": "Fertile window", "value": "Open until BBT confirms", "base": "fixed 6 days"}, {"key": "lh_rule", "label": "LH rule for Peak", "value": "1 high + CM ≥ watery"}, {"key": "bbt_confirm", "label": "BBT shift to confirm", "value": "+0.2 °C × 3 days"}, {"key": "min_signals", "label": "Min. signals for confidence", "value": "2 in last 5 days", "base": "2"}, {"key": "late_alert", "label": "Late-period alert", "value": "off", "base": "cycle + 3 days"}], "status_overrides": [{"status": "peak", "kind": "same", "copy": "“Peak fertility today”"}, {"status": "high_fertility", "kind": "same", "copy": "“High chance today”"}, {"status": "two_week_wait", "kind": "same", "copy": "“{dpo} DPO · test in {n} days”"}, {"status": "low_fertility", "kind": "rename", "rule": "renamed → Waiting for signs", "copy": "“Waiting for your body's signs”", "rename": "Waiting for signs"}], "notifications": [{"key": "window_opens", "title": "Fertile window opens", "detail": "Only after 2 LH highs (no calendar push)", "enabled": true}, {"key": "weekly_checkin", "title": "Weekly gentle check-in", "detail": "“Still waiting? That's normal with PCOS”", "enabled": true}, {"key": "test_day", "title": "Test day reminder", "detail": "12 DPO after confirmed ovulation", "enabled": true}, {"key": "late_period", "title": "Late period alert", "detail": "Disabled — long cycles are expected", "enabled": false}], "features": [{"key": "pcos_content", "title": "PCOS content & inositol tips", "detail": "Articles, nutrition, insulin", "enabled": true}, {"key": "cycle_ring", "title": "Cycle-day ring", "detail": "Replaced by “days since period”", "enabled": false}, {"key": "specialist_nudge", "title": "Specialist nudge", "detail": "After 6 months without confirmed ovulation", "enabled": true}, {"key": "community", "title": "Community: PCOS group", "detail": "Suggested on mode switch", "enabled": true}]}, "iui_ivf": {"meta": {"label": "IUI/IVF", "title": "Fertility treatment (IUI / IVF)", "color": "blue", "icon": "syringe", "description": "The clinic protocol drives the timeline. Ovulation is set by the trigger shot, not by signals. BBT is used only for luteal monitoring because progesterone support raises temperature."}, "weights": {"lh": 0.15, "cf": 0.05, "bbt": 0.0, "calendar": 0.0, "skin": 0.0, "protocol": 0.8}, "params": [{"key": "ovulation_time", "label": "Ovulation time", "value": "Trigger shot + 36 h", "note": "TTC: predicted from signals"}, {"key": "lh_after_trigger", "label": "LH after trigger", "value": "ignored", "hint": "avoid false peaks from hCG"}, {"key": "bbt_confirm", "label": "BBT shift confirmation", "value": "disabled", "hint": "progesterone raises BBT"}, {"key": "luteal", "label": "Luteal phase", "value": "From procedure date"}, {"key": "test_day", "label": "Test day", "value": "Clinic beta-hCG date", "note": "TTC: 12 DPO"}, {"key": "cycle_len", "label": "Cycle length", "value": "from protocol"}, {"key": "min_signals", "label": "Min. signals for confidence", "value": "n/a (protocol)"}], "status_overrides": [{"status": "stimulation", "kind": "extra", "rule": "protocol.phase = stimulation", "copy": "“Stimulation · day {n}”", "name": "Stimulation", "color": "amber"}, {"status": "trigger", "kind": "extra", "rule": "trigger_at set AND now < trigger+36h", "copy": "“Trigger shot tonight 21:00”", "name": "Trigger", "color": "pink"}, {"status": "procedure", "kind": "extra", "rule": "procedure_date = today", "copy": "“IUI today · 08:00”", "name": "Procedure", "color": "blue"}, {"status": "two_week_wait", "kind": "rule", "rule": "days_since_procedure ≥ 1", "entry": [[{"field": "days_since_procedure", "op": "≥", "value": "1"}]], "copy": "“Beta hCG on {date}”"}, {"status": "low_fertility", "kind": "hidden", "rule": "hidden during program", "name": "Low / High fertility"}], "notifications": [{"key": "med_reminders", "title": "Medication reminders", "detail": "Priority channel · exact time, even in quiet hours", "enabled": true}, {"key": "appointments", "title": "Appointment reminders", "detail": "Day before + 2 h before", "enabled": true}, {"key": "window_pushes", "title": "Fertile-window pushes", "detail": "Off — clinic manages timing", "enabled": false}, {"key": "partner_alert", "title": "Partner alert", "detail": "Procedure day & beta result day", "enabled": true}], "features": [{"key": "program_screen", "title": "Treatment program screen", "detail": "Stages, meds, appointments, labs", "enabled": true}, {"key": "home_ring", "title": "Home fertility ring", "detail": "Replaced by program stage bar", "enabled": false}, {"key": "clinic_sync", "title": "Clinic data sync", "detail": "Appointments & lab results (with consent)", "enabled": true}, {"key": "community", "title": "Community: IVF & IUI group", "detail": "Suggested on program start", "enabled": true}]}, "after_loss": {"meta": {"label": "After loss", "title": "Trying after pregnancy loss", "color": "purple", "icon": "heart", "description": "Gentler tone and fewer pushes. The first cycles after a loss are often irregular, so predictions stay hidden until 2 cycles are logged. Pregnancy countdowns and baby content are off by default."}, "weights": {"lh": 0.4, "cf": 0.25, "bbt": 0.2, "calendar": 0.1, "skin": 0.05, "protocol": 0}, "params": [{"key": "cycle_len", "label": "Valid cycle length", "value": "21–60 days", "note": "TTC: 21–45 · first cycles vary"}, {"key": "predictions_after", "label": "Predictions shown after", "value": "2 logged cycles", "note": "TTC: immediately"}, {"key": "fertile_window", "label": "Fertile window length", "value": "6 days"}, {"key": "lh_rule", "label": "LH rule for Peak", "value": "1 peak OR high + egg-white"}, {"key": "bbt_confirm", "label": "BBT shift to confirm", "value": "+0.2 °C × 3 days"}, {"key": "min_signals", "label": "Min. signals for confidence", "value": "2 in last 5 days"}, {"key": "late_alert", "label": "Late-period alert", "value": "off", "note": "avoid distress · opt-in"}], "status_overrides": [{"status": "peak", "kind": "same", "copy": "“A good day to try, if you feel ready”"}, {"status": "high_fertility", "kind": "same", "copy": "“Your fertile window is here”"}, {"status": "two_week_wait", "kind": "same", "rule": "same (countdown hidden)", "copy": "“Take it one day at a time”"}, {"status": "recovering", "kind": "extra", "rule": "cycles_since_loss < 2", "entry": [[{"field": "cycles_since_loss", "op": "<", "value": "2"}]], "copy": "“Your body is finding its rhythm”", "name": "Recovering", "color": "purple"}], "notifications": [{"key": "max_one_push", "title": "Max 1 push per day", "detail": "All cycle pushes merged", "enabled": true}, {"key": "test_day", "title": "Test day reminder", "detail": "Opt-in only", "enabled": false}, {"key": "wellbeing", "title": "Weekly wellbeing check-in", "detail": "Offers counsellor if 2× “Low”", "enabled": true}, {"key": "partner_alerts", "title": "Partner alerts", "detail": "Only if user re-enables", "enabled": false}], "features": [{"key": "countdown_confetti", "title": "Pregnancy countdown & confetti", "detail": "Hidden", "enabled": false}, {"key": "baby_content", "title": "Baby / pregnancy content", "detail": "Hidden in feed & articles", "enabled": false}, {"key": "counsellor", "title": "Free counsellor session", "detail": "Offered on mode start", "enabled": true}, {"key": "community", "title": "Community: After loss group (protected)", "detail": "Moderated by counsellor team", "enabled": true}]}}}$json$::jsonb, 'Fertile window 5 → 6 days', now());
